import { Suspense } from 'react'
import { RequestMetadata } from '@/components/request-metadata'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>
        <nav>Operations</nav>
        {/* The nav ships in the static shell; the per-request metadata streams in. */}
        <Suspense fallback={<aside>Loading request details…</aside>}>
          <RequestMetadata />
        </Suspense>
        {children}
      </body>
    </html>
  )
}

